<div class="sheet">

  <header class="head">
    <div class="brand">
      <svg class="mark" viewBox="0 0 64 64" role="img" aria-label="Tally mark: four strokes crossed by a fifth">
        <g class="mark-strokes"><path d="M17 13v38M27 12v40M37 13v38M47 12v40"/></g>
