    return { kind: 'error', message: `unknown command "${name}"; expected one of ${COMMANDS.join(', ')}` };
  }
  if (extra.length > 0) return { kind: 'error', message: `unexpected argument "${extra[0]}"` };

  let budgetUsd: number | undefined;
  if (values.budget !== undefined) {
    budgetUsd = Number(values.budget);
    if (!Number.isFinite(budgetUsd) || budgetUsd <= 0) {
      return { kind: 'error', message: `--budget must be a positive number of USD, got "${values.budget}"` };
    }
  }
  return {
    kind: 'command',
    command: name as Command,
    options: {
      config: values.config,
      dryRun: values['dry-run'],
      baseline: values.baseline,
      budgetUsd,
      only: values.only,
    },
  };
}

type Handler = (options: CliOptions, io: CliIO) => Promise<number>;

const stub =
  (command: Command): Handler =>
  async (_options, io) => {
    io.stdout(`tally ${command}: not implemented yet`);
    return 0;
  };

async function runCommand(options: CliOptions, io: CliIO): Promise<number> {
  try {
    const result = await runTally({
      configPath: options.config,
      dryRun: options.dryRun,
      baseline: options.baseline,
      budgetUsd: options.budgetUsd,
      only: options.only,
    });
    io.stdout(`wrote ${result.runStatePath}`);
    io.stdout(`wrote ${result.ledgerPath}`);
    io.stdout(`updated ${result.latestRunDir}`);
    io.stdout(`finished ${result.runState.runId}: ${result.runState.tasks.length} tasks, ${result.ledger.length} attempts`);
    return 0;
  } catch (e) {
    return reportError('tally run', e, io);
  }
}

async function demoCommand(_options: CliOptions, io: CliIO): Promise<number> {
  try {
    const result = await runDemo();
    io.stdout(`wrote ${result.runStatePath}`);
    io.stdout(`wrote ${result.ledgerPath}`);
    io.stdout(`updated ${result.latestRunDir}`);
    io.stdout(`finished ${result.runState.runId}: ${result.runState.tasks.length} tasks, ${result.ledger.length} attempts`);
    return 0;
  } catch (e) {
    return reportError('tally demo', e, io);
  }
}

function reportError(prefix: string, error: unknown, io: CliIO): number {
  if (error instanceof ConfigError || error instanceof BacklogError || error instanceof RunError) {
    io.stderr(`${prefix}: ${error.message}`);
    return 2;
  }
  throw error;
}

const handlers: Record<Command, Handler> = {
  run: runCommand,
import { mkdirSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import type { Ledger, RunState } from '../schema/index.js';

export const DEFAULT_LATEST_RUN_DIR = '.tally/runs/latest';

export interface WrittenRunFiles {
  outputDir: string;
  runStatePath: string;
  ledgerPath: string;
  latestRunDir: string;
}

function writeJson(path: string, value: unknown): void {
  writeFileSync(path, `${JSON.stringify(value, null, 2)}\n`);
}

export function writeRunFiles(outputDir: string, runState: RunState, ledger: Ledger, latestRunDir = DEFAULT_LATEST_RUN_DIR): WrittenRunFiles {
  const resolvedOutput = resolve(outputDir);
  const resolvedLatest = resolve(latestRunDir);
  mkdirSync(resolvedOutput, { recursive: true });
  mkdirSync(resolvedLatest, { recursive: true });

  const runStatePath = resolve(resolvedOutput, 'run.json');
  const ledgerPath = resolve(resolvedOutput, 'ledger.json');
  writeJson(runStatePath, runState);
  writeJson(ledgerPath, ledger);

  writeJson(resolve(resolvedLatest, 'run.json'), runState);
  writeJson(resolve(resolvedLatest, 'ledger.json'), ledger);
  return { outputDir: resolvedOutput, runStatePath, ledgerPath, latestRunDir: resolvedLatest };
}

