# Draft backlog for https://github.com/Vaibhaav-Tiwari/fly-doom-jev.
# Do not file these as issues until the user approves them. The checks below
# are based on a scratch clone at f99b54c, where `make test` passed.
version: 1
kind: tally-draft-backlog

repo:
  slug: Vaibhaav-Tiwari/fly-doom-jev
  baseBranch: main
  observedCommit: f99b54c

test:
  setupCommand: make setup
  command: make test
  notes: Fresh clone test result from lane A was 90 passed in 7.53s.

tasks:
  - id: FDJ-1
    title: Add replay loader coverage for malformed recording files
    size: small
    label: tally
    body: |
      The replay loader already rejects a recording with no header, but it does
      not have focused coverage for malformed JSONL rows or frame metadata with
      a missing pattern. Add defensive tests and the smallest loader changes
      needed so a bad recording reports a clear exception instead of failing
      later in the API.
    passCheck: .venv/bin/python -m pytest tests/unit/test_recording.py -q

  - id: FDJ-2
    title: Include goal fields in encoded state tests
    size: small
    label: tally
    body: |
      `EnvironmentState` has a `goal` field for E1M1 strategy, but the unit
      tests only assert the older threat and serialization fields. Add coverage
      proving that a goal dict can be attached, serialized, and omitted for
      ordinary arena observations without breaking the existing schema version.
    passCheck: .venv/bin/python -m pytest tests/unit/test_state_encoder.py -q

  - id: FDJ-3
    title: Test POST /new rejects unknown live scenarios
    size: small
    label: tally
    body: |
      The live API validates scenario names in `request_new_episode`, but there
      is no direct API-level test for a bad `POST /new` body. Add a small test
      around the FastAPI route or the loop method so an unknown scenario returns
      a clear error and leaves the current scenario unchanged.
    passCheck: .venv/bin/python -m pytest tests/unit/test_jev_live.py -q

  - id: FDJ-4
    title: Preserve recording summary when both summary and episode_end rows exist
    size: medium
    label: tally
    body: |
      `load_recording` treats both `summary` and `episode_end` rows as the
      recording summary. Make the behavior explicit and deterministic when a
      file contains both rows, then add a regression test that documents which
      one wins and why. Keep the public replay response shape unchanged.
    passCheck: .venv/bin/python -m pytest tests/unit/test_recording.py tests/integration/test_closed_loop.py -q

  - id: FDJ-5
    title: Add action-weighting regression for missing MOVEMENT_INTENT metadata
    size: medium
    label: tally
    body: |
      `jev_action_weights` reads optional movement-intent probabilities from
      decision metadata. Add coverage for decisions that have probabilities but
      no `choice_probabilities` key, and make the implementation tolerate that
      shape without changing the existing weighting semantics.
    passCheck: .venv/bin/python -m pytest tests/unit/test_weighting.py tests/unit/test_jev.py -q

  - id: FDJ-6
    title: Make plasticity checkpoint errors actionable
    size: medium
    label: tally
    body: |
      A corrupt or incompatible plasticity checkpoint should fail with a message
      that names the checkpoint path and provenance mismatch instead of a raw
      NumPy exception. Add tests for corrupt checkpoint data and mismatched
      config hashes, then keep the fresh-start fallback for ordinary provenance
      mismatch.
    passCheck: .venv/bin/python -m pytest tests/unit/test_plasticity.py -q

  - id: FDJ-7
    title: Add deterministic featured-recording generation for the static showcase
    size: medium
    difficultyNote: looks medium but is hard
    label: tally
    body: |
      The project now serves a static GitHub Pages showcase from curated
      recordings. Add a deterministic packaging path that writes `featured.json`
      in a stable order, verifies every referenced recording and frame exists,
      and fails loudly when a curated bundle is incomplete. This looks medium
      because it is packaging code, but it crosses replay metadata, static
      assets, and CLI behavior.
    passCheck: .venv/bin/python -m pytest tests/unit/test_recording.py tests/unit/test_hf_export.py -q
// Tally dashboard. Reads run.json and ledger.json on a timer and redraws.
// It never writes anything.

import { frameAt } from './replay-core.js';

const NANOS_PER_USD = 1_000_000_000;

const query = new URLSearchParams(location.search);
const defaults = window.TALLY_DASHBOARD ?? {};
const asFolder = (path) => (path.endsWith('/') ? path : `${path}/`);
const hasExplicitData = query.has('data');
const wantsDemo = query.has('demo');
const wantsReplay = query.has('replay');
const config = {
  data: asFolder(query.get('data') ?? defaults.data ?? './'),
  baseline: query.get('baseline') ?? defaults.baseline ?? null,
  intervalMs: Math.max(250, Number(query.get('interval') ?? defaults.intervalMs ?? 2000) || 2000),
  sample: defaults.sample ?? null,
  // ?demo shows the checked-in sample. ?replay=60 plays the chosen run over that many seconds.
  useSample: wantsDemo || (wantsReplay && !hasExplicitData),
  replaySec: wantsReplay ? Math.max(5, Number(query.get('replay')) || 60) : null,
};
if (config.baseline) config.baseline = asFolder(config.baseline);

// ---------- formatting ----------

const esc = (value) =>
  String(value ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);

/** Only http(s) links are rendered; anything else in the data is shown as plain text. */
const safeUrl = (url) => (typeof url === 'string' && /^https?:\/\//i.test(url) ? url : null);

function usd(nanos) {
  const value = (nanos ?? 0) / NANOS_PER_USD;
  const digits = value !== 0 && Math.abs(value) < 0.01 ? 4 : 2;
  return `$${value.toLocaleString('en-US', { minimumFractionDigits: digits, maximumFractionDigits: digits })}`;
}

const count = (n) => (n ?? 0).toLocaleString('en-US');

function minutes(fromIso, toIso) {
  const span = Math.max(0, new Date(toIso) - new Date(fromIso));
  const mins = Math.round(span / 60000);
  if (mins < 1) return `${Math.round(span / 1000)} s`;
  return mins < 60 ? `${mins} min` : `${Math.floor(mins / 60)} h ${mins % 60} min`;
}

const clock = (iso) => new Date(iso).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

const link = (url, text) => {
  const href = safeUrl(url);
  return href ? `<a href="${esc(href)}" target="_blank" rel="noopener">${esc(text)}</a>` : '';
};

const isRunning = (row) => row.result === 'running' || (!row.endedAt && !['passed', 'failed', 'stopped', 'error'].includes(row.result));

// ---------- reading ----------

async function readJson(url) {
  const response = await fetch(url, { cache: 'no-store' });
  if (!response.ok) throw new Error(`${response.status} ${response.statusText}`.trim());
  return response.json();
}

async function readRun(folder) {
  const [run, ledger] = await Promise.all([readJson(`${folder}run.json`), readJson(`${folder}ledger.json`)]);
  if (!run || !Array.isArray(run.tasks) || !run.budget) throw new Error('run.json is not a Tally run');
  if (!Array.isArray(ledger)) throw new Error('ledger.json is not a list of attempts');
  return { run, ledger: ledger.filter((row) => row.runId === run.runId || !row.runId) };
}

// ---------- drawing ----------

/** Replaces a section's markup only when it changed, so links and selections survive a poll. */
function draw(id, html) {
  const node = document.getElementById(id);
  if (node.__html === html) return;
  node.__html = html;
  node.innerHTML = html;
}

const passedCount = (run) => run.tasks.filter((task) => task.status === 'passed').length;
const perMergedPr = (run) => (passedCount(run) > 0 ? run.budget.spentNanos / passedCount(run) : null);

/** Tally marks: groups of four strokes crossed by a fifth. */
function tallyMarks(n) {
  const groups = [];
  for (let left = n; left > 0; left -= 5) {
    const strokes = Math.min(left, 4);
    const crossed = left >= 5;
    const lines = Array.from({ length: strokes }, (_, i) => `<path d="M${5 + i * 7} 3v22"/>`).join('');
    const slash = crossed ? '<path d="M1 22 30 7"/>' : '';
    groups.push(`<svg viewBox="0 0 ${crossed ? 32 : strokes * 7 + 3} 28" aria-hidden="true">${lines}${slash}</svg>`);
  }
  return groups.join('');
}

function drawRun(run) {
  const mode = run.mode === 'baseline' ? 'Baseline: every task on the strongest model' : 'Routed by Tally';
  const state =
    run.status === 'finished'
      ? `Finished in ${minutes(run.startedAt, run.endedAt ?? run.updatedAt)}`
      : run.status === 'interrupted'
        ? `Interrupted after ${minutes(run.startedAt, run.updatedAt)}`
        : `<span class="live"></span>Running, ${minutes(run.startedAt, run.updatedAt)} in`;
  draw(
    'run',
    `<div><dt>Repository</dt><dd>${esc(run.repo)}</dd></div>
     <div><dt>Run</dt><dd>${esc(run.runId)}</dd></div>
     <div><dt>Routing</dt><dd>${mode}</dd></div>
     <div><dt>State</dt><dd>${state}</dd></div>`,
  );
}

function drawNotice(run, source) {
  const lines = [];
  if (source.sample) lines.push(`Sample data: this page is reading the bundled fixture at ${esc(config.sample)}, not a live Tally run.`);
  if (source.replaying) lines.push('Replay of a finished run, speeded up. Nothing is running now.');
  if (run.dryRun) lines.push('Simulated run: the workers are scripted and no money is spent.');
