import { describe, expect, it } from 'vitest';

import { displayedCost, withLiveCosts } from './live-state.js';

describe('live dashboard state', () => {
  it('shows an in-progress ledger row as a running task with cost climbing toward its ceiling', () => {
    const startedAt = '2026-10-10T00:00:00.000Z';
    const state = {
      run: {
        status: 'running',
        updatedAt: startedAt,
        budget: { source: 'config', limitNanos: 1_000_000_000, spentNanos: 0 },
        tasks: [
          {
            taskId: 'T1',
            title: 'Live task',
            status: 'pending',
            statusReason: null,
            attempts: 0,
            tier: null,
            model: null,
            spentNanos: 0,
            escalated: false,
            prUrl: null,
          },
        ],
      },
      ledger: [
        {
          taskId: 'T1',
          attempt: 1,
          tier: 'middle',
          model: 'claude',
          estimatedCostNanos: 0,
          ceilingNanos: 1_000_000_000,
          result: 'failed',
          endedAt: null,
          startedAt,
        },
      ],
    };

    const live = withLiveCosts(state, {
      nowMs: new Date('2026-10-10T00:01:00.000Z').getTime(),
      liveCeilingSec: 120,
    });

    expect(live.run.tasks[0]).toMatchObject({
      status: 'running',
      attempts: 1,
      tier: 'middle',
      model: 'claude',
      spentNanos: 500_000_000,
    });
    expect(displayedCost(live.ledger[0])).toBe(500_000_000);
    expect(live.ledger[0].displayIsLiveEstimate).toBe(true);
    expect(live.run.budget.spentNanos).toBe(500_000_000);
  });

  it('leaves finished runs on their recorded costs', () => {
    const state = {
      run: {
        status: 'finished',
        budget: { source: 'config', limitNanos: 1_000_000_000, spentNanos: 123 },
        tasks: [{ taskId: 'T1', status: 'passed', spentNanos: 123 }],
      },
      ledger: [{ taskId: 'T1', estimatedCostNanos: 123, ceilingNanos: 1_000_000_000, result: 'passed', endedAt: '2026-10-10T00:01:00.000Z' }],
    };

    expect(withLiveCosts(state, { nowMs: new Date('2026-10-10T00:30:00.000Z').getTime() })).toBe(state);
  });
});

import { describe, expect, it } from 'vitest';

import { displayedCost, withLiveCosts } from './live-state.js';

describe('live dashboard state', () => {
  it('shows an in-progress ledger row as a running task with cost climbing toward its ceiling', () => {
    const startedAt = '2026-10-10T00:00:00.000Z';
    const state = {
      run: {
        status: 'running',
        updatedAt: startedAt,
        budget: { source: 'config', limitNanos: 1_000_000_000, spentNanos: 0 },
        tasks: [
          {
            taskId: 'T1',
            title: 'Live task',
            status: 'pending',
            statusReason: null,
            attempts: 0,
            tier: null,
            model: null,
            spentNanos: 0,
            escalated: false,
            prUrl: null,
          },
        ],
      },
      ledger: [
        {
          taskId: 'T1',
          attempt: 1,
          tier: 'middle',
          model: 'claude',
          estimatedCostNanos: 0,
          ceilingNanos: 1_000_000_000,
          result: 'failed',
          endedAt: null,
          startedAt,
        },
      ],
    };

    const live = withLiveCosts(state, {
      nowMs: new Date('2026-10-10T00:01:00.000Z').getTime(),
      liveCeilingSec: 120,
    });

    expect(live.run.tasks[0]).toMatchObject({
      status: 'running',
      attempts: 1,
      tier: 'middle',
      model: 'claude',
      spentNanos: 500_000_000,
    });
    expect(displayedCost(live.ledger[0])).toBe(500_000_000);
    expect(live.ledger[0].displayIsLiveEstimate).toBe(true);
    expect(live.run.budget.spentNanos).toBe(500_000_000);
  });

  it('leaves finished runs on their recorded costs', () => {
