<title>Tally</title>
<link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'%3E%3Crect width='64' height='64' fill='%23f2e8d0'/%3E%3Cg stroke='%2317130d' stroke-width='5' stroke-linecap='round'%3E%3Cpath d='M17 13v38M27 12v40M37 13v38M47 12v40'/%3E%3C/g%3E%3Cpath d='M8 46 56 18' stroke='%23cf2e17' stroke-width='5' stroke-linecap='round'/%3E%3C/svg%3E">
<link rel="stylesheet" href="styles.css">
</head>
<body>
<div class="sheet">

